arguments.command:
cat > src/CheckoutPricing.Application/CheckoutCalculator.cs <<'E'
namespace CheckoutPricing.Application;

public static class CheckoutCalculator
{
    public static decimal CalculatePayableTotal(string customerTier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysApprovedTotal95()
    {
        Assert.Equal(95.00m, CheckoutCalculator.CalculatePayableTotal("Gold", 100.00m));
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

